const languageKey = 'agustin-language';
let pageLanguage = 'es';
try { if (localStorage.getItem(languageKey) === 'en') pageLanguage = 'en'; } catch {}
const t = value => pageLanguage === 'en' ? english.get(value) ?? value : value;

// Keep the original labels so switching language doesn't rebuild or clear the form.
const staticTranslations = [];
const textWalker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (textWalker.nextNode()) {
  const node = textWalker.currentNode;
  const original = node.nodeValue;
  const value = original.trim();
  if (english.has(value)) staticTranslations.push(() => { node.nodeValue = original.replace(value, t(value)); });
}
for (const attr of ['aria-label', 'placeholder', 'content']) {
  for (const el of document.querySelectorAll(`[${attr}]`)) {
    const value = el.getAttribute(attr);
    if (english.has(value)) staticTranslations.push(() => el.setAttribute(attr, t(value)));
  }
}
const originalPageTitle = document.title;
english.set(originalPageTitle, 'Agustín Mansilla | Software Developer');
function translatePage() {
  document.documentElement.lang = pageLanguage;
  document.title = t(originalPageTitle);
  for (const update of staticTranslations) update();
  for (const button of document.querySelectorAll('[data-lang]')) {
    button.setAttribute('aria-pressed', String(button.dataset.lang === pageLanguage));
  }
}
